import { common } from '@kit.AbilityKit';
import { preferences } from '@kit.ArkData';
import { SitePickerViewModel } from './SitePickerViewModel';
import { SiteRecord, cloneDocument, emptyDocument, readNumber, readObjectList } from './SitePickerModels';

const SITES_PREFERENCES_NAME: string = 'wordpress_sites';
const SITES_KEY: string = 'sites';
const ACTIVE_SITE_KEY: string = 'active_site';

/** Durable access to the sites the user owns. */
export interface SiteRepository {
  loadSites(): Promise<SiteRecord[]>;
  refreshSites(): Promise<SiteRecord[]>;
  saveSite(record: SiteRecord): Promise<SiteRecord>;
  activateSite(localId: number): Promise<void>;
  activeLocalId(): number;
}

/**
 * Repository backed by the application's own durable documents.
 *
 * `refreshSites` rejects when the stored catalog cannot be read, which is what
 * lets the picker leave its refreshing state and keep the last usable list.
 */
export class LocalSiteRepository implements SiteRepository {
  private readonly prefs: preferences.Preferences;
  private catalog: SiteRecord[] = [];
  private active: number = -1;

  constructor(context: common.UIAbilityContext) {
    this.prefs = preferences.getPreferencesSync(context, SITES_PREFERENCES_NAME);
  }

  async loadSites(): Promise<SiteRecord[]> {
    const stored: string = this.prefs.getSync(SITES_KEY, '[]') as string;
    this.catalog = this.decode(stored);
    this.active = readNumber(this.prefs.getSync(ACTIVE_SITE_KEY, this.encodeActive()) as Record<string, Object>, 'value', -1);
    return this.catalog;
  }

  async refreshSites(): Promise<SiteRecord[]> {
    const stored: string = this.prefs.getSync(SITES_KEY, '[]') as string;
    let decoded: SiteRecord[] = this.catalog;
    try {
      decoded = this.decode(stored);
    } catch (failure) {
      throw new Error('Stored sites are unreadable');
    }
    if (decoded.length === 0 && this.catalog.length > 0) {
      // The durable copy could not be produced; keep serving the cached catalog
      // but report the failure so the picker can retry later.
      throw new Error('Site refresh could not be completed');
    }
    this.catalog = decoded;
    return this.catalog;
  }

  async saveSite(record: SiteRecord): Promise<SiteRecord> {
    const stored: string = this.prefs.getSync(SITES_KEY, '[]') as string;
    const catalog: SiteRecord[] = this.decode(stored);
    if (catalog.length === 0) {
      catalog.push(record);
    } else {
      let replaced: boolean = false;
      for (let index = 0; index < catalog.length; index++) {
        if (catalog[index].localId === record.localId) {
          catalog[index] = record;
          replaced = true;
          break;
        }
      }
      if (!replaced) {
        catalog.push(record);
      }
    }
    this.catalog = catalog;
    this.write(catalog);
    return record;
  }

  async activateSite(localId: number): Promise<void> {
    this.active = localId;
    this.prefs.putSync(ACTIVE_SITE_KEY, this.encodeActive());
    this.prefs.flush();
  }

  activeLocalId(): number {
    return this.active;
  }

  private encodeActive(): string {
    return JSON.stringify(cloneDocument(this.documentOfNumber('value', this.active))) as string;
  }

  private documentOfNumber(key: string, value: number): Record<string, Object> {
    const document: Record<string, Object> = emptyDocument();
    document[key] = value;
    return document;
  }

  private decode(stored: string): SiteRecord[] {
    if (stored === undefined || stored === null || stored.length === 0) {
      return [];
    }
    const document: Record<string, Object> = JSON.parse(stored) as Record<string, Object>;
    return SitePickerViewModel.normalize(readObjectList(document, 'sites'));
  }

  private write(catalog: SiteRecord[]): void {
    const document: Record<string, Object> = emptyDocument();
    document['sites'] = JSON.parse(JSON.stringify(catalog)) as Object[];
    this.prefs.putSync(SITES_KEY, JSON.stringify(document));
    this.prefs.flush();
  }
}

