/**
 * Compatibility entry point for the previous store location.
 *
 * The picker store itself now lives with the rest of the site picker feature;
 * this alias keeps the historical import path working.
 */
export { SitePickerStore, SitePickerStore as LegacySitePickerStore } from '../feature/SitePickerStore';

import { common } from '@kit.AbilityKit';
import { MountedSitePickerPageOwner, SitePickerPageRuntime } from './SitePickerPageOwner';
import {
  SITE_ACTION_NONE,
  SITE_ACTION_PIN,
  SITE_EMPTY_NO_MATCHES,
  SITE_MODE_DEFAULT,
  SITE_REFRESH_FAILED,
  SITE_RESULT_ERROR,
  SITE_RESULT_SELECTED,
  SITE_SECTION_ALL,
  SITE_SECTION_PINNED,
  SITE_SECTION_RECENT,
  SITE_SECTION_SEARCH,
  SitePickerCommandEvent,
  SitePickerRow,
  SitePickerSnapshot,
  SitePickerStoreObserver,
  emptyDocument
} from '../feature/SitePickerModels';
import { AppSitePickerEffects } from '../feature/SitePickerEffects';
import { LocalSiteRepository } from '../feature/SiteRepository';

class PickerListItem {
  key: string = '';
  isHeader: boolean = false;
  title: string = '';
  subtitle: string = '';
  localId: number = -1;
  pinned: boolean = false;
  active: boolean = false;
  selectEnabled: boolean = true;
  pinControlVisible: boolean = false;

  static header(section: string): PickerListItem {
    const item: PickerListItem = new PickerListItem();
    item.key = 'header:' + section;
    item.isHeader = true;
    item.title = Index.sectionTitle(section);
    return item;
  }

  static site(row: SitePickerRow): PickerListItem {
    const item: PickerListItem = new PickerListItem();
    item.key = 'site:' + row.localId.toString();
    item.isHeader = false;
    item.title = row.name;
    item.subtitle = row.host;
    item.localId = row.localId;
    item.pinned = row.pinned;
    item.active = row.active;
    item.selectEnabled = row.selectEnabled;
    item.pinControlVisible = row.pinControlVisible;
    return item;
  }
}

class IndexStoreObserver implements SitePickerStoreObserver {
  private listener: ((state: Record<string, Object>) => void) | undefined = undefined;

  onSitePickerStateChanged(state: Record<string, Object>): void {
    const notify: ((state: Record<string, Object>) => void) | undefined = this.listener;
    if (notify !== undefined) {
      notify(state);
    }
  }
}

@Entry
@Component
struct Index {
  private owner?: MountedSitePickerPageOwner = undefined;
  private observer: IndexStoreObserver = new IndexStoreObserver();
  private alive: boolean = true;
  @State view: SitePickerSnapshot = new SitePickerSnapshot();
  @State items: PickerListItem[] = [];
  @State query: string = '';
  @State status: string = '';
  @State busy: boolean = false;

  aboutToAppear(): void {
    this.alive = true;
    void this.bootstrap();
  }

  aboutToDisappear(): void {
    this.alive = false;
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner !== undefined) {
      owner.unsubscribe(this.observer);
      owner.release();
    }
    this.owner = undefined;
  }

  private async bootstrap(): Promise<void> {
    const host = this.getUIContext().getHostContext();
    const context: common.UIAbilityContext = host as common.UIAbilityContext;
    if (!SitePickerPageRuntime.isConfigured()) {
      const repository: LocalSiteRepository = new LocalSiteRepository(context);
      const sites = await repository.loadSites();
      const state: Record<string, Object> = new SitePickerCommandEvent()
        .put('mode', SITE_MODE_DEFAULT)
        .put('pickerOpen', true)
        .put('actionMode', SITE_ACTION_NONE)
        .put('storeSites', JSON.parse(JSON.stringify(sites)) as Object[])
        .put('selectedLocalId', repository.activeLocalId())
        .build();
      SitePickerPageRuntime.configure(context, {
        state: state,
        persistence: emptyDocument(),
        leaf: new AppSitePickerEffects(repository)
      });
    }
    if (!this.alive) {
      return;
    }
    const owner: MountedSitePickerPageOwner = SitePickerPageRuntime.createOwner();
    this.owner = owner;
    this.observer.listener = () => {
      this.reload();
    };
    await owner.waitUntilReady();
    if (!this.alive) {
      owner.release();
      return;
    }
    owner.subscribe(this.observer);
    this.reload();
  }

  private reload(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined || !this.alive) {
      return;
    }
    const view: SitePickerSnapshot = owner.snapshot();
    this.view = view;
    this.query = view.searchQuery;
    this.items = Index.buildItems(view);
    this.status = Index.statusOf(view);
  }

  private static buildItems(view: SitePickerSnapshot): PickerListItem[] {
    const items: PickerListItem[] = [];
    for (let index = 0; index < view.sections.length; index++) {
      const section = view.sections[index];
      if (section.localIds.length === 0) {
        continue;
      }
      items.push(PickerListItem.header(section.name));
      for (let inner = 0; inner < view.rows.length; inner++) {
        const row: SitePickerRow = view.rows[inner];
        if (row.section === section.name) {
          items.push(PickerListItem.site(row));
        }
      }
    }
    return items;
  }

  private static sectionTitle(section: string): string {
    if (section === SITE_SECTION_PINNED) {
      return 'Pinned';
    }
    if (section === SITE_SECTION_RECENT) {
      return 'Recent';
    }
    if (section === SITE_SECTION_SEARCH) {
      return 'Search results';
    }
    return SITE_SECTION_ALL === section ? 'All sites' : section;
  }

  private static statusOf(view: SitePickerSnapshot): string {
    if (view.refreshStatus === SITE_REFRESH_FAILED) {
      return 'Refresh failed. Your sites are still listed, try again.';
    }
    if (view.resultStatus === SITE_RESULT_SELECTED) {
      return 'Site selected.';
    }
    if (view.resultStatus === SITE_RESULT_ERROR) {
      return 'That site is no longer available.';
    }
    return '';
  }

  private run(action: Promise<void>): void {
    this.busy = true;
    action.then(() => {
      this.busy = false;
      this.reload();
    }).catch(() => {
      this.busy = false;
      this.reload();
    });
  }

  private onQueryChanged(value: string): void {
    this.query = value;
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.search(value));
  }

  private onClearSearch(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.clearSearch());
  }

  private onRowClick(item: PickerListItem): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.tapSiteRow(item.localId));
  }

  private onPinClick(localId: number, pinned: boolean): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.setPinned(localId, !pinned));
  }

  private onTogglePinEditing(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(this.view.actionMode === SITE_ACTION_PIN ? owner.endPinEditing() : owner.beginPinEditing());
  }

  private onRefresh(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.refresh());
  }

  private onAddSite(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.invoke('addSite', emptyDocument()));
  }

  build() {
    Column({ space: 10 }) {
      Row({ space: 12 }) {
        Text('Sites').fontSize(24).fontWeight(FontWeight.Bold).layoutWeight(1)
        if (this.view.addSiteVisible) {
          Text('Add site').fontSize(14).fontColor('#0A64FF').onClick(() => this.onAddSite())
        }
      }.width('100%')

      Row({ space: 8 }) {
        TextInput({ text: this.query, placeholder: 'Search sites' })
          .layoutWeight(1)
          .height(40)
          .onChange((value: string) => this.onQueryChanged(value))
        if (this.view.searchExpanded) {
          Text('Clear').fontSize(14).fontColor('#0A64FF').onClick(() => this.onClearSearch())
        }
      }.width('100%')

      Row({ space: 16 }) {
        if (!this.view.restricted) {
          Text(this.view.actionMode === SITE_ACTION_PIN ? 'Done' : 'Edit pins')
            .fontSize(14)
            .fontColor(this.view.actionMode === SITE_ACTION_PIN ? '#0A64FF' : '#5C5C5C')
            .onClick(() => this.onTogglePinEditing())
        }
        Text('Refresh').fontSize(14).fontColor('#5C5C5C').onClick(() => this.onRefresh())
        Blank()
        if (this.busy || this.view.refreshing) {
          LoadingProgress().width(20).height(20).color('#0A64FF')
        }
      }.width('100%')

      if (this.view.actionMode === SITE_ACTION_PIN) {
        Text('Pinning mode. Use the pin control on a site; rows stay inactive until you finish.')
          .fontSize(12)
          .fontColor('#5C5C5C')
          .width('100%')
      }

      if (this.status.length > 0) {
        Text(this.status).fontSize(12).fontColor('#5C5C5C').width('100%')
      }

      if (this.items.length === 0) {
        Column({ space: 8 }) {
          Text(this.view.emptyMessage).fontSize(14).fontColor('#5C5C5C')
          if (this.view.emptyState === SITE_EMPTY_NO_MATCHES) {
            Text('Clear search').fontSize(14).fontColor('#0A64FF').onClick(() => this.onClearSearch())
          }
        }.width('100%').padding({ top: 32 })
      } else {
        List({ space: 0 }) {
          ForEach(this.items, (item: PickerListItem) => {
            if (item.isHeader) {
              Row() {
                Text(item.title).fontSize(13).fontWeight(FontWeight.Medium).fontColor('#5C5C5C')
              }.width('100%').padding({ top: 16, bottom: 6 })
            } else {
              Row({ space: 12 }) {
                Column({ space: 2 }) {
                  Text(item.title).fontSize(16).maxLines(1)
                  if (item.subtitle.length > 0) {
                    Text(item.subtitle).fontSize(12).fontColor('#5C5C5C').maxLines(1)
                  }
                }.alignItems(HorizontalAlign.Start).layoutWeight(1)
                if (item.active) {
                  Text('Active').fontSize(12).fontColor('#0A64FF')
                }
                if (item.pinControlVisible) {
                  Text(item.pinned ? 'Unpin' : 'Pin')
                    .fontSize(13)
                    .fontColor('#0A64FF')
                    .padding({ left: 12 })
                    .onClick(() => this.onPinClick(item.localId, item.pinned))
                }
              }
              .width('100%')
              .padding({ top: 10, bottom: 10 })
              .onClick(() => this.onRowClick(item))
            }
          }, (item: PickerListItem) => item.key)
        }
        .layoutWeight(1)
        .width('100%')
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .alignItems(HorizontalAlign.Start)
  }
}

