    if (view.resultStatus === SITE_RESULT_SELECTED) {
      return 'Site selected.';
    }
    if (view.resultStatus === SITE_RESULT_ERROR) {
      return 'That site is no longer available.';
    }
    return '';
  }

  private run(action: Promise<void>): void {
    this.busy = true;
    action.then(() => {
      this.busy = false;
      this.reload();
    }).catch(() => {
      this.busy = false;
      this.reload();
    });
  }

  private onQueryChanged(value: string): void {
    this.query = value;
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.search(value));
  }

  private onClearSearch(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.clearSearch());
  }

  private onRowClick(item: PickerListItem): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.tapSiteRow(item.localId));
  }

  private onPinClick(localId: number, pinned: boolean): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.setPinned(localId, !pinned));
  }

  private onTogglePinEditing(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(this.view.actionMode === SITE_ACTION_PIN ? owner.endPinEditing() : owner.beginPinEditing());
  }

  private onRefresh(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.refresh());
  }

  private onAddSite(): void {
    const owner: MountedSitePickerPageOwner | undefined = this.owner;
    if (owner === undefined) {
      return;
    }
    this.run(owner.invoke('addSite', emptyDocument()));
  }

  build() {
    Column({ space: 10 }) {
      Row({ space: 12 }) {
        Text('Sites').fontSize(24).fontWeight(FontWeight.Bold).layoutWeight(1)
        if (this.view.addSiteVisible) {
          Text('Add site').fontSize(14).fontColor('#0A64FF').onClick(() => this.onAddSite())
        }
      }.width('100%')

      Row({ space: 8 }) {
        TextInput({ text: this.query, placeholder: 'Search sites' })
          .layoutWeight(1)
          .height(40)
          .onChange((value: string) => this.onQueryChanged(value))
        if (this.view.searchExpanded) {
          Text('Clear').fontSize(14).fontColor('#0A64FF').onClick(() => this.onClearSearch())
        }
      }.width('100%')

      Row({ space: 16 }) {
        if (!this.view.restricted) {
          Text(this.view.actionMode === SITE_ACTION_PIN ? 'Done' : 'Edit pins')
            .fontSize(14)
            .fontColor(this.view.actionMode === SITE_ACTION_PIN ? '#0A64FF' : '#5C5C5C')
            .onClick(() => this.onTogglePinEditing())
        }
        Text('Refresh').fontSize(14).fontColor('#5C5C5C').onClick(() => this.onRefresh())
        Blank()
        if (this.busy || this.view.refreshing) {
          LoadingProgress().width(20).height(20).color('#0A64FF')
        }
      }.width('100%')

      if (this.view.actionMode === SITE_ACTION_PIN) {
        Text('Pinning mode. Use the pin control on a site; rows stay inactive until you finish.')
          .fontSize(12)
          .fontColor('#5C5C5C')
          .width('100%')
      }

      if (this.status.length > 0) {
        Text(this.status).fontSize(12).fontColor('#5C5C5C').width('100%')
      }

      if (this.items.length === 0) {
        Column({ space: 8 }) {
          Text(this.view.emptyMessage).fontSize(14).fontColor('#5C5C5C')
          if (this.view.emptyState === SITE_EMPTY_NO_MATCHES) {
            Text('Clear search').fontSize(14).fontColor('#0A64FF').onClick(() => this.onClearSearch())
          }
        }.width('100%').padding({ top: 32 })
      } else {
        List({ space: 0 }) {
          ForEach(this.items, (item: PickerListItem) => {
            if (item.isHeader) {
              Row() {
                Text(item.title).fontSize(13).fontWeight(FontWeight.Medium).fontColor('#5C5C5C')
              }.width('100%').padding({ top: 16, bottom: 6 })
            } else {
              Row({ space: 12 }) {
                Column({ space: 2 }) {
                  Text(item.title).fontSize(16).maxLines(1)
                  if (item.subtitle.length > 0) {
                    Text(item.subtitle).fontSize(12).fontColor('#5C5C5C').maxLines(1)
                  }
                }.alignItems(HorizontalAlign.Start).layoutWeight(1)
                if (item.active) {
                  Text('Active').fontSize(12).fontColor('#0A64FF')
                }
                if (item.pinControlVisible) {
                  Text(item.pinned ? 'Unpin' : 'Pin')
                    .fontSize(13)
                    .fontColor('#0A64FF')
                    .padding({ left: 12 })
                    .onClick(() => this.onPinClick(item.localId, item.pinned))
                }
              }
              .width('100%')
              .padding({ top: 10, bottom: 10 })
              .onClick(() => this.onRowClick(item))
            }
          }, (item: PickerListItem) => item.key)
        }
        .layoutWeight(1)
        .width('100%')
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .alignItems(HorizontalAlign.Start)
  }
