private write(catalog: SiteRecord[]): void {
    const document: Record<string, Object> = emptyDocument();
    document['sites'] = JSON.parse(JSON.stringify(catalog)) as Object[];
    this.prefs.putSync(SITES_KEY, JSON.stringify(document));
    this.prefs.flush();
  }
}

/**
 * Fallback used when the durable site store cannot be opened at all. Reads stay
 * empty so the picker can report that no site is available, and a refresh fails
 * loudly instead of pretending the list is fresh.
 */
export class UnavailableSiteRepository implements SiteRepository {
  async loadSites(): Promise<SiteRecord[]> {
    return [];
  }

  async refreshSites(): Promise<SiteRecord[]> {
    throw new Error('The site store is not available');
  }

  async saveSite(record: SiteRecord): Promise<SiteRecord> {
    throw new Error('The site store is not available');
  }

  async activateSite(localId: number): Promise<void> {
    throw new Error('The site store is not available');
  }

  activeLocalId(): number {
    return -1;
  }
}

